import{_ as i,o,c as a,a3 as c}from"./chunks/framework.CqzWVxDX.js";const u=JSON.parse('{"title":"GOOSE 按设备作用域全栈重构","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/iec61850/25-goose-device-scoped-refactoring.md","filePath":"changelog/iec61850/25-goose-device-scoped-refactoring.md","lastUpdated":1783757019000}'),l={name:"changelog/iec61850/25-goose-device-scoped-refactoring.md"};function r(t,e,s,d,n,h){return o(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="goose-按设备作用域全栈重构" tabindex="-1">GOOSE 按设备作用域全栈重构 <a class="header-anchor" href="#goose-按设备作用域全栈重构" aria-label="Permalink to &quot;GOOSE 按设备作用域全栈重构&quot;">​</a></h1><p>日期：2026-07-11</p><h2 id="变更摘要" tabindex="-1">变更摘要 <a class="header-anchor" href="#变更摘要" aria-label="Permalink to &quot;变更摘要&quot;">​</a></h2><ul><li>Publisher、Receiver、Subscription 和抓包会话均按 IEC 61850 <code>channel_id</code> 隔离。</li><li>Publisher 和 Receiver 支持选择后端发现的真实网卡；无效、禁用或环回网卡不能启动 GOOSE。</li><li>Publisher 支持完整协议配置编辑，数据集条目支持批量、事务化替换。</li><li>Receiver/Subscription 新增数据库持久化，应用重启后可恢复并支持 <code>auto_start</code>。</li><li>Subscription 支持编辑 APPID、MAC、DataSetRef、ConfRev 和描述。</li><li>发现的 GOOSE 控制块不再自动写入配置，必须选择网卡并显式确认导入。</li><li>SCL/ICD 导入默认不覆盖现有 GOOSE 配置，仅在明确开启自动创建时写入。</li><li>WebSocket 抓包命令和报文广播按通道隔离，避免设备之间串包。</li></ul><h2 id="数据库升级" tabindex="-1">数据库升级 <a class="header-anchor" href="#数据库升级" aria-label="Permalink to &quot;数据库升级&quot;">​</a></h2><p>启动时会自动创建 <code>goose_receiver</code>、<code>goose_subscription</code> 表，并为旧版 <code>goose_publisher</code> 补齐显示名称、描述和自动启动字段。Publisher 原有数据继续保留。</p><h2 id="新增接口" tabindex="-1">新增接口 <a class="header-anchor" href="#新增接口" aria-label="Permalink to &quot;新增接口&quot;">​</a></h2><ul><li><code>GET /api/network-interfaces</code></li><li><code>POST /api/network-interfaces/validate</code></li><li><code>POST /api/channels/goose/publishers/entries/replace</code></li><li><code>POST /api/channels/goose/receivers/update</code></li><li><code>POST /api/channels/goose/receivers/subscriptions/replace</code></li></ul><p>原有 GOOSE API 继续保留，但列表和资源操作增加 <code>channel_id</code>，用于设备归属校验。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ul><li>Ruff 全量检查通过。</li><li>前端 Vue/TypeScript 类型检查及生产构建通过。</li><li>GOOSE 设备隔离、完整配置更新、Receiver 持久化和原有抓包测试共 6 项通过。</li></ul>',11)])])}const _=i(l,[["render",r]]);export{u as __pageData,_ as default};
